13	declare_lint_rule! {
14	    /// Enforce that aria-hidden="true" is not set on focusable elements.
15	    ///
16	    /// `aria-hidden="true"` can be used to hide purely decorative content from screen reader users.
17	    /// A focusable element with `aria-hidden="true"` can be reached by keyboard.
18	    /// This can lead to confusion or unexpected behavior for screen reader users.
19	    ///
20	    /// ## Examples
21	    ///
22	    /// ### Invalid
23	    ///
24	    /// ```html,expect_diagnostic
25	    /// <div aria-hidden="true" tabindex="0"></div>
26	    /// ```
27	    ///
28	    /// ```html,expect_diagnostic
29	    /// <a href="/" aria-hidden="true">link</a>
30	    /// ```
31	    ///
32	    /// ### Valid
33	    ///
34	    /// ```html
35	    /// <div aria-hidden="true"></div>
36	    /// ```
37	    ///
38	    /// ```html
39	    /// <button aria-hidden="true" tabindex="-1"></button>
40	    /// ```
41	    ///
42	    /// ## Resources
43	    ///
44	    /// - [aria-hidden elements do not contain focusable elements](https://dequeuniversity.com/rules/axe/html/4.4/aria-hidden-focus)
45	    /// - [Element with aria-hidden has no content in sequential focus navigation](https://www.w3.org/WAI/standards-guidelines/act/rules/6cfa84/proposed/)
46	    /// - [MDN aria-hidden](https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Attributes/aria-hidden)
47	    ///
48	    pub NoAriaHiddenOnFocusable {
49	        version: "next",
50	        name: "noAriaHiddenOnFocusable",
51	        language: "html",
52	        sources: &[RuleSource::EslintJsxA11y("no-aria-hidden-on-focusable").same()],
53	        recommended: true,
54	        severity: Severity::Error,
55	        fix_kind: FixKind::Unsafe,
56	    }
57	}
