127	/// Parses the tabindex attribute value as an integer.
128	///
129	/// Returns `None` if the attribute has no value or cannot be parsed as an integer.
130	/// Non-integer values (e.g., `tabindex="abc"`) are ignored and treated as if
131	/// tabindex was not set.
132	fn get_tabindex_value(attribute: &HtmlAttribute) -> Option<i32> {
133	    let value = attribute.value()?;
134	    value.trim().parse::<i32>().ok()
135	}
136	
137	/// Returns whether the element is natively focusable per the HTML spec.
138	///
139	/// Returns `Some(true)` when the element is one of:
140	/// - Interactive elements: `<button>`, `<select>`, `<textarea>`, `<details>`, `<summary>`
141	/// - Elements with `href` attribute: `<a href="...">`, `<area href="...">`
142	/// - `<input>` elements, except `<input type="hidden">` which is not focusable
143	/// - Elements with a truthy `contenteditable` attribute (editing hosts)
144	///
145	/// Returns `Some(false)` when the element is recognized but not focusable.
