declare_lint_rule! {
    /// Enforce that ARIA state and property values are valid.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```html,expect_diagnostic
    /// <span role="checkbox" aria-checked="test">some text</span>
    /// ```
    ///
    /// ```html,expect_diagnostic
    /// <span aria-labelledby="">some text</span>
    /// ```
    ///
    /// ```html,expect_diagnostic
    /// <span aria-valuemax="hey">some text</span>
    /// ```
    ///
    /// ```html,expect_diagnostic
    /// <span aria-orientation="hey">some text</span>
    /// ```
    ///
    /// ### Valid
    ///
    /// ```html
    /// <span role="checkbox" aria-checked="true">some text</span>
    /// <span aria-labelledby="fooId barId">some text</span>
    /// ```
    ///
    /// ## Accessibility guidelines
    ///
    /// - [WCAG 4.1.2](https://www.w3.org/WAI/WCAG21/Understanding/name-role-value)
    ///
    /// ### Resources
    ///
    /// - [ARIA Spec, States and Properties](https://www.w3.org/TR/wai-aria/#states_and_properties)
    /// - [Chrome Audit Rules, AX_ARIA_04](https://github.com/GoogleChrome/accessibility-developer-tools/wiki/Audit-Rules#ax_aria_04)
    pub UseValidAriaValues {
        version: "next",
        name: "useValidAriaValues",
        language: "html",
        sources: &[RuleSource::EslintJsxA11y("aria-proptypes").same()],
        recommended: true,
        severity: Severity::Error,
    }
}

pub struct UseValidAriaValuesState {
    attribute_name: TokenText,
    attribute_range: TextRange,
    property_type: AriaValueType,
}

impl Rule for UseValidAriaValues {
    type Query = Ast<HtmlAttribute>;
    type State = UseValidAriaValuesState;
    type Signals = Option<Self::State>;
    type Options = UseValidAriaValuesOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let node = ctx.query();
        let name_token = node.name().ok()?.value_token().ok()?;
        let name = name_token.text_trimmed();

        // In plain HTML, attribute names are case-insensitive, so `ARIA-HIDDEN`
        // and `aria-hidden` refer to the same attribute. In component templates
        // (Vue, Svelte, Astro), attribute names are case-sensitive.
        let is_html = ctx.source_type::<HtmlFileSource>().is_html();
        let aria_attribute = if is_html {
            AriaAttribute::from_str(&name.to_ascii_lowercase())
        } else {
            AriaAttribute::from_str(name)
        }
        .ok()?;

        let value_type = aria_attribute.value_type();

        // A valueless ARIA attribute (e.g. `<div aria-hidden>`) is treated as
        // having the value `true`.
        let is_valid = match node.initializer() {
            None => value_type.contains("true"),
            Some(_) => value_type.contains(node.value().unwrap_or_default().text()),
        };

        if is_valid {
            return None;
        }

        Some(UseValidAriaValuesState {
            attribute_name: name_token.token_text_trimmed(),
            attribute_range: node.range(),
            property_type: value_type,
        })
    }

    fn diagnostic(_ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        let attribute_name = state.attribute_name.text();
        let diagnostic = RuleDiagnostic::new(
            rule_category!(),
            state.attribute_range,
            markup! {
                "The value of the ARIA attribute "<Emphasis>{attribute_name}</Emphasis>" is not correct."
            },
        );
        let diagnostic = match state.property_type {
            AriaValueType::Boolean => diagnostic.footer_list(
                markup! {
                    "The only supported values for the "<Emphasis>{attribute_name}</Emphasis>" property are:"
                },
                ["false", "true"],
            ),
            AriaValueType::OptionalBoolean => diagnostic.footer_list(
                markup! {
                    "The only supported values for the "<Emphasis>{attribute_name}</Emphasis>" property are:"
                },
                ["undefined", "false", "true"],
            ),
            AriaValueType::Tristate => diagnostic.footer_list(
                markup! {
                    "The only supported values for the "<Emphasis>{attribute_name}</Emphasis>" property are:"
                },
                ["false", "true", "mixed"],
            ),
            AriaValueType::Integer | AriaValueType::Number => diagnostic.note(markup! {
                "The only supported value is a number."
            }),
            AriaValueType::IdReference => diagnostic.note(markup! {
                "The only supported value is an HTML identifier."
            }),
            AriaValueType::IdReferenceList => diagnostic.note(markup! {
                "The only supported value is a space-separated list of HTML identifiers."
            }),
            AriaValueType::String => diagnostic.note(markup! {
                "The only supported value is text."
            }),
            AriaValueType::Token(tokens) => diagnostic.footer_list(
                markup! {
                    "The only supported value for the "<Emphasis>{attribute_name}</Emphasis>" property is one of the following:"
                },
                tokens.iter().copied(),
            ),
            AriaValueType::TokenList(tokens) => diagnostic.footer_list(
                markup! {
                    "The values supported for the "<Emphasis>{attribute_name}</Emphasis>" property are one or more of the following:"
                },
                tokens.iter().copied(),
            ),
        };
        Some(diagnostic.note(markup! {
            "Use a valid value for the "<Emphasis>{attribute_name}</Emphasis>" attribute according to the WAI-ARIA specification."
        }))
    }
}
